"""Apply deterministic frontend syntax repairs, navigation, copy, and service catalog updates before build."""
from pathlib import Path

path = Path("src/App.js")
source = path.read_text()

# About() must close its React fragment before Industries().
source = source.replace("</main>}\nfunction Industries", "</main></>}\nfunction Industries", 1)

# Keep the streamed chat parser's separator as a normal escaped literal.
source = source.replace("const parts=buf.split('\\n\\n');", "const parts=buf.split('\\n\\n');", 1)

# Homepage hero: make the introduction longer, distinctive and human-friendly.
hero_old_1 = "Design, Manufacturing, Installation — all under one roof. NA Engineering Solutions is your trusted partner for engineering, construction, industrial solutions, general order supplies and project support."
hero_old_2 = "From the first conversation to the final handover, we make engineering and industrial work easier to manage. NA Engineering Solutions brings together practical engineering, dependable supplies, skilled installation and project support — so you have one trusted team to turn your requirements into real, workable solutions."
hero_new = "From a single requirement to a complete project, NA Engineering Solutions brings people, engineering expertise and dependable supply together under one roof. We support businesses with Civil Engineering, HVAC, Mechanical Engineering, PEB Works, Electrical Works, Fire Fighting and Safety & Security solutions, along with General Order Supplies & Services. Whether you need a planned installation, reliable industrial materials or hands-on project support, our focus is simple: understand what you need, deliver the right solution and stay with you through execution."
source = source.replace(hero_old_1, hero_new, 1)
source = source.replace(hero_old_2, hero_new, 1)

# Partner section: keep the service-rich version separate from the hero.
partner_old = "NA Engineering Solutions provides reliable engineering, construction, industrial and project support services along with general order supplies for commercial, industrial and construction requirements."
partner_new = "We help businesses move from requirement to reality with one dependable engineering partner. Our team brings together Civil Engineering, HVAC, Mechanical Engineering, PEB Works, Electrical Works, Fire Fighting and Safety & Security — backed by General Order Supplies & Services for the materials, equipment and support your project needs. From planned work to urgent site requirements, we focus on practical solutions, clear communication and dependable execution."
source = source.replace(partner_old, partner_new, 1)

# Remove the short footer tagline shown above the footer bottom bar.
source = source.replace('<span>Built for dependable project delivery.</span>', '', 1)

# Put General Order Supplies before Services in the header navigation.
old_nav = "const nav=[['Home','/'],['Services','/services'],['General Order Supplies','/supplies'],['Industries','/industries'],['Our Clients','/clients'],['Contact','/contact']];"
new_nav = "const nav=[['Home','/'],['General Order Supplies','/supplies'],['Services','/services'],['Industries','/industries'],['Our Clients','/clients'],['Contact','/contact']];"
source = source.replace(old_nav, new_nav, 1)

# Replace service images with images that actually match each service.
image_replacements = {
    "https://images.unsplash.com/photo-1565008447742-97f6f38c985c": "https://www.gettyimages.com/",
    "https://images.unsplash.com/photo-1615309662243-70f6df917b59": "https://mojoair.com.au/assets/images/web-image-industrial.jpg",
    "https://images.unsplash.com/photo-1558618666-fcd25c85cd64": "https://www.mpofcinci.com/wp-content/uploads/2025/09/shutterstock_2551326641-1024x768.webp",
    "https://images.unsplash.com/photo-1429497419816-9ca5cfb4571a": "https://kksteel.in/wp-content/uploads/2021/10/pre-engineered-buildings-considered-1.jpg",
    "https://images.unsplash.com/photo-1473341304170-971dccb5ac1e": "https://www.eabel.com/wp-content/uploads/2024/11/Worker-adjusting-components-in-a-control-panel.webp",
    "https://images.unsplash.com/photo-1523861751938-121b5323b48b": "https://www.masararabia.com/assets/images/products/safety-equipment/fire-and-safety-equipment.webp",
    "https://images.unsplash.com/photo-1567954970774-58d6aa6c50dc": "https://www.buchen-group.be/fileadmin/_processed_/6/1/csm_BUCHEN-_DSC4125-2-FINAL_teaser_033546d692.webp",
}
for old_url, new_url in image_replacements.items():
    source = source.replace(old_url, new_url)

# Add the new industrial supply/service categories requested for the Services section.
service_marker = '  { slug:"safety-security", title:"Safety & Security", icon:ShieldCheck, image:"https://www.buchen-group.be/fileadmin/_processed_/6/1/csm_BUCHEN-_DSC4125-2-FINAL_teaser_033546d692.webp", text:"PPE, helmets, shoes, gloves, goggles, coveralls, masks and facility safety requirements." },\n];'
service_additions = '''  { slug:"mechanical-electrical-supplies-services", title:"Mechanical & Electrical Supplies and Services", icon:Wrench, image:"https://www.mpofcinci.com/wp-content/uploads/2025/09/shutterstock_2551326641-1024x768.webp", text:"Industrial motors, gearboxes, pumps, blowers, compressors, conveyors, bearings, valves, fittings, electrical panels, breakers, cables and on-site repair support — supplied and supported by NA Engineering Solutions." },\n  { slug:"utilities-facility-maintenance", title:"Utilities & Facility Maintenance Supplies and Services", icon:Wrench, image:"https://images.unsplash.com/photo-1581578731548-c64695cc6952", text:"Practical maintenance support for water, compressed air, steam and building utilities, including consumables, compressor parts, boiler parts, preventive maintenance and AMC support." },\n  { slug:"boiler-chemicals-supply-services", title:"Boiler Chemicals – Supply and Services", icon:FlaskConical, image:"https://haoshpumps.com/wp-content/uploads/2024/01/Boiler-Chemical-for-Dosing-Pump.jpg", text:"Boiler water-treatment chemicals, dosing support, testing and practical recommendations to help improve efficiency and protect equipment from scale and corrosion." },\n  { slug:"seamless-ms-ss-pipes-fittings", title:"Seamless MS & SS Pipes and Fittings", icon:Wrench, image:"https://maximt.au/assets/images/instrumental/gauge_Root_Valves%20.png", text:"Seamless Mild Steel and Stainless Steel pipes, fittings, flanges, elbows, reducers and tees in project-specific sizes, grades and schedules." },\n  { slug:"wastewater-treatment-plant-supplies-services", title:"Wastewater Treatment Plant (WWTP) Supplies and Services", icon:Factory, image:"https://www.gettyimages.com/", text:"WWTP pumps, blowers, diffusers, dosing systems and treatment chemicals, with operation, maintenance and performance-improvement support." },\n  { slug:"waterproofing-solutions", title:"Waterproofing Solutions – Supplies and Services", icon:Building2, image:"https://www.constructionlondon.co.uk/gallery/6695/8f21032a-3505-476c-9dee-f9ffa11326ff.jpg", text:"Waterproofing materials and application for roofs, basements, water tanks and wet areas, including leakage rectification and long-term protection." },\n  { slug:"pumps-valves-pneumatic-fittings", title:"Pumps, Valves, and Pneumatic Fittings", icon:Wrench, image:"https://www.rivistacmi.it/uploads/tx_etim/RS_COMPONENTS-pneumatics-image.jpg", text:"Industrial pumps, process valves, pneumatic fittings, hoses, regulators and accessories selected around the application, duty and site requirement." },\n];'''
if service_marker in source and 'mechanical-electrical-supplies-services' not in source:
    source = source.replace(service_marker, service_marker.replace('\n];', '\n' + service_additions), 1)

# Add detailed, natural service-page feature lists.
features_marker = '"Safety & Security":["PPE, helmets, shoes, gloves and goggles","Coveralls, masks and safety accessories","Industrial safety products","Security systems and facility safety requirements"]};'
features_expanded = '"Safety & Security":["PPE, helmets, shoes, gloves and goggles","Coveralls, masks and safety accessories","Industrial safety products","Security systems and facility safety requirements"],"Mechanical & Electrical Supplies and Services":["Industrial motors, gearboxes, pumps, blowers and compressors","Belt conveyors, bearings, gaskets, valves, fittings, pipes and flanges","Electrical panels, breakers, contactors, relays, cables and lighting","Repair, replacement, troubleshooting and on-site technical support","Hand pallet lifter parts, hand trolleys, platform trolleys and pallet jacks","Ropes, chains and cargo straps for material-handling requirements"],"Utilities & Facility Maintenance Supplies and Services":["Water, compressed-air and steam utility maintenance support","Gaskets, fasteners, seals, bearings, belts and other maintenance consumables","Preventive and corrective maintenance for plant and building facilities","AMC support tailored to the client’s operational needs","Air compressor parts supply and service support","Boiler parts supply and service support"],"Boiler Chemicals – Supply and Services":["Scale inhibitors, oxygen scavengers and pH-control chemicals","Dosing systems and routine monitoring support","On-site testing, analysis and practical recommendations","Support for boiler efficiency, corrosion control and scale prevention"],"Seamless MS & SS Pipes and Fittings":["Seamless Mild Steel and Stainless Steel pipes","Project-specific grades, schedules, sizes and specifications","Flanges, elbows, reducers, tees and related fittings","Sourcing support for maintenance and new project requirements"],"Wastewater Treatment Plant (WWTP) Supplies and Services":["Pumps, blowers, diffusers and dosing systems","Coagulants, flocculants, disinfectants and treatment chemicals","Operation and maintenance support for existing WWTPs","Practical guidance for performance improvement and reliable operation"],"Waterproofing Solutions – Supplies and Services":["Waterproof chemicals, coatings and membranes","Roof, basement, water-tank and wet-area waterproofing","Leakage inspection and rectification support","Long-term protection planned around the site’s actual condition"],"Pumps, Valves, and Pneumatic Fittings":["Centrifugal, submersible and dosing pumps","Gate, globe, butterfly, check and ball valves","Pneumatic fittings, hoses, regulators and accessories","Selection support based on process, pressure, flow and application"]};'
if features_marker in source and '"Mechanical & Electrical Supplies and Services":["Industrial motors' not in source:
    source = source.replace(features_marker, features_expanded, 1)

# Give every service page a fuller, human-friendly introduction and a clear company-specific closing CTA.
old_detail = 'function ServiceDetail({service}){return <><PageIntro eyebrow={`SERVICES / ${service.title.toUpperCase()}`} title={service.title}>{service.text}</PageIntro><main className="section section-light"><div className="container detail-grid"><img className="detail-image" src={img(service.image)} alt={`${service.title} professional project`} /><div><SectionLabel>WHAT WE SUPPORT</SectionLabel><h2>Practical support for demanding environments.</h2><p>We help customers plan, source and execute the work required to keep their sites, systems and projects operating effectively. Scope is agreed around your requirements and site conditions.</p><ul className="feature-list">{(detailFeatures[service.title]||[]).map(x=><li key={x}><CheckCircle2 size={17}/>{x}</li>)}</ul></div></div></main></>}'
new_detail = '''function ServiceDetail({service}){const extended={"Mechanical & Electrical Supplies and Services":{"heading":"The right industrial item, without the runaround.","intro":"At NA Engineering Solutions, we help maintenance and project teams source the mechanical and electrical items they actually need — from a replacement motor or bearing to a complete package of equipment and site support.","close":"Tell us the equipment, make, model or specification and our team will help you work out the practical supply or service route."},"Utilities & Facility Maintenance Supplies and Services":{"heading":"Keep the facility running, not waiting.","intro":"NA Engineering Solutions supports plant and facility teams with the everyday maintenance materials and technical help that keep utilities dependable. We can work around planned shutdowns, recurring maintenance needs or urgent breakdowns.","close":"Share your utility or facility requirement with NA Engineering Solutions and we can shape the supply, maintenance or AMC scope around your site."},"Boiler Chemicals – Supply and Services":{"heading":"Boiler treatment built around the way your system actually runs.","intro":"NA Engineering Solutions supplies boiler-treatment chemicals and supports the routine checks that help operators manage scale, corrosion and water-quality issues. We focus on practical recommendations rather than a one-size-fits-all chemical list.","close":"If you are seeing scale, corrosion, carryover or unstable boiler-water readings, talk to NA Engineering Solutions about the next sensible step."},"Seamless MS & SS Pipes and Fittings":{"heading":"Pipes and fittings matched to the job.","intro":"NA Engineering Solutions supplies seamless MS and SS pipes and related fittings for maintenance, fabrication and new project requirements. We work from your required size, grade, schedule and quantity so the material fits the application.","close":"Send us your pipe or fitting specification and NA Engineering Solutions can help with sourcing and supply."},"Wastewater Treatment Plant (WWTP) Supplies and Services":{"heading":"Practical support for water-treatment operations.","intro":"NA Engineering Solutions supplies key WWTP equipment, treatment chemicals and maintenance support for facilities that need their treatment systems to perform consistently. We can also help identify where operating performance is falling short.","close":"For a WWTP equipment, chemical or maintenance requirement, share the process details with NA Engineering Solutions and we will help define the scope."},"Waterproofing Solutions – Supplies and Services":{"heading":"Fix the water problem at its source.","intro":"NA Engineering Solutions provides waterproofing materials and application support for roofs, basements, tanks and wet areas. We look at the condition of the surface, the source of the leakage and the protection the area needs before recommending a system.","close":"If water is getting where it should not, send NA Engineering Solutions the site details and we can discuss the most suitable repair or waterproofing approach."},"Pumps, Valves, and Pneumatic Fittings":{"heading":"Components selected for the process, not just the catalogue.","intro":"NA Engineering Solutions supplies pumps, valves and pneumatic components for industrial applications, with selection support based on duty, flow, pressure, connection and operating conditions.","close":"Share your existing part number, datasheet or application details and NA Engineering Solutions can help identify a suitable supply option."}}[service.title]||{};return <><PageIntro eyebrow={`SERVICES / ${service.title.toUpperCase()}`} title={service.title}>{service.text}</PageIntro><main className="section section-light"><div className="container detail-grid"><img className="detail-image" src={img(service.image)} alt={`${service.title} professional project`} /><div><SectionLabel>NA ENGINEERING SOLUTIONS / WHAT WE SUPPORT</SectionLabel><h2>{extended.heading||'Practical support for demanding environments.'}</h2><p>{extended.intro||`NA Engineering Solutions helps customers plan, source and execute the work required to keep their sites, systems and projects operating effectively. We keep the scope practical and build it around your requirements and site conditions.`}</p><ul className="feature-list">{(detailFeatures[service.title]||[]).map(x=><li key={x}><CheckCircle2 size={17}/>{x}</li>)}</ul><p className="detail-closing">{extended.close||`Tell NA Engineering Solutions what you are working with, and we will help shape the right scope for your site, project or maintenance requirement.`}</p><Button to="/contact" secondary testid={`service-contact-${service.slug}`}>Discuss This Requirement</Button></div></div></main></>}'''
if old_detail in source and 'const extended={' not in source:
    source = source.replace(old_detail, new_detail, 1)

path.write_text(source)

# Expand the footer vertically while preserving the existing layout and responsive behavior.
css_path = path.parent / "App.css"
css = css_path.read_text()
footer_css = "\n/* Expanded footer layout */\n.footer{padding:105px 0 30px;min-height:500px}.footer-grid{gap:60px}.footer-intro{max-width:310px;margin:28px 0}.footer h4{margin-bottom:28px}.footer-grid>div:not(:first-child){gap:16px}.footer-grid a,.footer-grid span{font-size:13px;line-height:1.75}.footer-bottom{margin-top:82px;padding-top:22px}\n@media(max-width:800px){.footer{padding:80px 0 26px;min-height:0}.footer-grid{gap:42px}.footer-bottom{margin-top:55px}}\n@media(max-width:480px){.footer{padding:70px 0 24px}.footer-grid{gap:36px}.footer-bottom{margin-top:45px}}\n"
if "/* Expanded footer layout */" not in css:
    css_path.write_text(css + footer_css)

# Make the new service pages feel complete without changing the site's existing visual language.
detail_css = "\n/* Expanded service detail content */\n.detail-closing{margin:24px 0 22px;max-width:640px}.detail-grid .button{margin-top:4px}\n"
if "/* Expanded service detail content */" not in css:
    css_path.write_text(css_path.read_text() + detail_css)

print("Frontend syntax repairs, homepage copy, header navigation order, expanded service catalog, detailed service pages, expanded footer styling, and footer tagline removal applied before build.")
